   SECTION 6 — Common Table Expressions (CTEs) (Tasks 6.1 - 6.6)
   ============================================================================= */

-- Task 6.1: Rewrite this derived table query as a CTE
WITH StoreCounts AS (
    SELECT 
        store_id, 
        COUNT(*) AS order_count
    FROM sales.orders
    GROUP BY store_id
)
SELECT 
    AVG(CAST(order_count AS FLOAT)) AS avg_orders
FROM StoreCounts;
GO


-- Task 6.2: Write a CTE called cte_high_value_products that returns products with list_price > 2000
WITH cte_high_value_products AS (
    SELECT
        product_id,
        product_name,
        brand_id,
        category_id,
        model_year,
        list_price
    FROM production.products
    WHERE list_price > 2000
)
SELECT
    hvp.product_id,
    hvp.product_name,
    c.category_id,
    c.category_name,
    hvp.list_price
FROM cte_high_value_products AS hvp
INNER JOIN production.categories AS c
    ON hvp.category_id = c.category_id
WHERE c.category_name = 'Mountain Bikes'
ORDER BY hvp.list_price DESC;
GO


-- Task 6.3: Write two CTEs in one WITH clause: order count & revenue per customer
WITH CustomerOrderCounts AS (
    SELECT
        customer_id,
        COUNT(order_id) AS order_count
    FROM sales.orders
    GROUP BY customer_id
),
CustomerRevenue AS (
    SELECT
        o.customer_id,
        SUM(oi.quantity * oi.list_price * (1.0 - oi.discount)) AS total_revenue
    FROM sales.orders AS o
    INNER JOIN sales.order_items AS oi
        ON o.order_id = oi.order_id
    GROUP BY o.customer_id
)
SELECT
    coc.customer_id,
    coc.order_count,
    CAST(cr.total_revenue AS DECIMAL(14, 2)) AS total_revenue
FROM CustomerOrderCounts AS coc
INNER JOIN CustomerRevenue AS cr
    ON coc.customer_id = cr.customer_id
ORDER BY total_revenue DESC;
GO


-- Task 6.4: Using a recursive CTE, generate numbers 1 to 10 with squares
WITH NumberSequence AS (
    SELECT 
        1 AS n,
        1 * 1 AS square

    UNION ALL

    SELECT 
        n + 1,
        (n + 1) * (n + 1)
    FROM NumberSequence
    WHERE n < 10
)
SELECT 
    n, 
    square
FROM NumberSequence;
GO


-- Task 6.5: Recursive CTE org chart showing manager's first_name and level hierarchy
WITH StaffOrgChart AS (
    SELECT
        staff_id,
        first_name,
        last_name,
        manager_id,
        CAST(NULL AS VARCHAR(50)) AS manager_first_name,
        0 AS level
    FROM sales.staffs
    WHERE manager_id IS NULL

    UNION ALL

    SELECT
        e.staff_id,
        e.first_name,
        e.last_name,
        e.manager_id,
        CAST(m.first_name AS VARCHAR(50)) AS manager_first_name,
        m.level + 1 AS level
    FROM sales.staffs AS e
    INNER JOIN StaffOrgChart AS m
        ON e.manager_id = m.staff_id
)
SELECT
    staff_id,
    first_name + ' ' + last_name AS employee_name,
    manager_id,
    manager_first_name,
    level
FROM StaffOrgChart
ORDER BY level, staff_id;
GO


-- Task 6.6: Think About It: CTE Execution & Materialization
-- Claim: "CTEs are faster because the database computes once and reuses it."
-- Answer: Inaccurate. CTEs are logical/inline constructs; SQL Server re-evaluates
-- the CTE definition for every reference in the query.
-- To compute once and reuse, use a Temporary Table (#temp_table) or Table Variable.


